package vn.edu.eaut.lab6.listener; import jakarta.servlet.*;import jakarta.servlet.annotation.WebListener;import vn.edu.eaut.lab6.store.StudentStore;@WebListener public class AppContextListener implements ServletContextListener{public void contextInitialized(ServletContextEvent e){StudentStore.initSampleData();e.getServletContext().setAttribute("studentCount",StudentStore.count());System.out.println("Ung dung Lab 6 da khoi dong. So SV mau: "+StudentStore.count());}public void contextDestroyed(ServletContextEvent e){System.out.println("Ung dung Lab 6 da dung. So SV: "+StudentStore.count());}}
